using Microsoft.EntityFrameworkCore;
using System.Text.Json;
using System.Text.Json.Nodes;
using System.Net.Mail;

namespace Society.Api;

public record MemberCard(Guid Id, Guid? PersonId, string Number, string FullName, Guid ChapterId, string Chapter, string Region, Guid CategoryId, string Category, string Status, DateTimeOffset JoinedAt, int Revision, string? Designation, string? Photo, string? City, object? Professional, object? Contacts, bool Administrative);
public class MembershipService(AppDb db, Access access)
{
    public const string DefaultPrivacy = "{\"directory\":true,\"photo\":false,\"contacts\":false,\"professional\":false}";
    public static readonly string[] Statuses = ["Active", "Inactive", "Suspended", "Resigned", "Closed", "Deceased"];
    public static async Task<List<Guid>> Ancestors(AppDb db, Guid tenant, Guid chapter) => await db.Database.SqlQuery<Guid>($"""
WITH RECURSIVE ancestors AS (SELECT "Id","ParentId" FROM "Units" WHERE "TenantId"={tenant} AND "Id"={chapter} UNION ALL SELECT p."Id",p."ParentId" FROM "Units" p JOIN ancestors a ON p."Id"=a."ParentId" WHERE p."TenantId"={tenant}) SELECT "Id" AS "Value" FROM ancestors
""").ToListAsync();
    public static Task<int> Lock(AppDb db, Guid tenant) => db.Database.ExecuteSqlInterpolatedAsync($"SELECT pg_advisory_xact_lock(hashtext({tenant.ToString()}))");
    public async Task<MembershipPolicyRecord> Policy(Guid tenant, Guid chapter) => await db.MembershipPolicies.AsNoTracking().Where(x => x.TenantId == tenant && (x.ChapterId == chapter || x.ChapterId == null)).OrderByDescending(x => x.ChapterId != null).FirstOrDefaultAsync() ?? new MembershipPolicyRecord { TenantId = tenant };
    public static JsonObject Json(string value) { try { if (value.Length > 64000) throw new Exception(); var node=JsonNode.Parse(value)!.AsObject();bool Invalid(JsonNode? n)=>n switch{JsonObject o=>o.Any(p=>p.Key.Contains('\0')||Invalid(p.Value)),JsonArray a=>a.Any(Invalid),JsonValue v=>v.TryGetValue<string>(out var text)&&text.Contains('\0'),_=>false};if(Invalid(node))throw new Exception();return node; } catch { throw new DomainException("Use a JSON object of up to 64 KB"); } }
    public static void ValidateProfile(string value) { var p = Json(value); if (p["renewalReminders"] is { } reminder && !(reminder is JsonValue rv && rv.TryGetValue<bool>(out _))) throw new DomainException("Renewal reminder preference must be true or false"); foreach (var field in new[] { "organizationName", "preferredName", "email", "workEmail", "phone", "city", "state", "country", "dateOfBirth", "anniversary", "gender", "languages", "photoUrl", "pincode", "maritalStatus", "spouseName", "education", "specialization", "institution", "graduationYear", "employmentStatus", "bloodGroup", "emergencyContactName", "emergencyContactPhone", "otherInformation" }) if (p[field] is { } node && !(node is JsonValue scalar && scalar.TryGetValue<string>(out var textValue) && textValue.Length <= 4000)) throw new DomainException("Profile fields must be text up to 4000 characters"); foreach (var field in new[] { "mobiles", "addresses" }) if (p[field] is { } array && !(array is JsonArray items && items.Count <= 20 && items.All(v => v is JsonValue scalar && scalar.TryGetValue<string>(out var textValue) && textValue.Length <= 4000))) throw new DomainException("Addresses and additional mobiles must be lists of up to twenty text entries"); if (p["professional"] is { } pro && !(pro is JsonObject professional && professional.Count <= 20 && professional.All(pair => pair.Value is JsonValue scalar && scalar.TryGetValue<string>(out var textValue) && textValue.Length <= 4000))) throw new DomainException("Professional fields must contain text values"); foreach (var key in new[] { "dateOfBirth", "anniversary" }) if (p[key] is JsonValue date && date.TryGetValue<string>(out var dateText) && dateText != "" && !DateOnly.TryParseExact(dateText, "yyyy-MM-dd", System.Globalization.CultureInfo.InvariantCulture, System.Globalization.DateTimeStyles.None, out _)) throw new DomainException("Use an ISO calendar date for birth date and anniversary"); if (p["phone"] is JsonValue phone && phone.TryGetValue<string>(out var phoneText) && phoneText != "" && !System.Text.RegularExpressions.Regex.IsMatch(phoneText, "^[+()0-9 .-]{3,30}$")) throw new DomainException("Enter a valid mobile number"); foreach (var key in new[] { "email", "workEmail" }) if (p[key] is JsonValue v && v.TryGetValue<string>(out var text) && !string.IsNullOrEmpty(text) && !MailAddress.TryCreate(text, out _)) throw new DomainException("Enter a valid contact email"); if (p["photoUrl"] is JsonValue photo && photo.TryGetValue<string>(out var url) && url.Length > 0 && !url.StartsWith("/api/v1/societies/") && (!Uri.TryCreate(url, UriKind.Absolute, out var uri) || uri.Scheme != "https")) throw new DomainException("Use an uploaded photograph or HTTPS image"); }
    public static void ValidatePrivacy(string value) { var p = Json(value); foreach (var key in new[] { "directory", "photo", "contacts", "professional", "communication" }) if (p[key] is { } v && !(v is JsonValue x && x.TryGetValue<bool>(out _))) throw new DomainException("Privacy choices must be true or false"); }
    public async Task Chapter(Guid tenant, Guid id) { if (!await db.Units.AnyAsync(x => x.TenantId == tenant && x.Id == id && x.Status == "Active" && db.Levels.Any(l => l.Id == x.LevelId && l.Kind == "Chapter"))) throw new DomainException("Choose an active chapter in this society"); }
    public async Task Category(Guid tenant, Guid id) { if (!await db.MembershipCategories.AnyAsync(x => x.TenantId == tenant && x.Id == id && x.Active)) throw new DomainException("Choose an active membership category"); }
    public async Task<Person> PersonForAccount(Guid user) { var p = await db.Persons.SingleOrDefaultAsync(x => x.UserId == user); if (p != null) return p; var account = await db.Users.SingleAsync(x => x.Id == user); p = new Person { UserId = user, FullName = account.FullName, SearchName = account.FullName.ToLowerInvariant() }; db.Persons.Add(p); return p; }
    public async Task<bool> IsSelf(Membership m) => await MembershipExperience.Owned(db, access.UserId, true).AnyAsync(x => x.TenantId == m.TenantId && x.Id == m.Id);
    public IQueryable<Membership> Administrative(Guid tenant, string permission = "members.read") { var units = access.Visible(tenant, permission).Select(x => x.Id); return db.Memberships.Where(x => x.TenantId == tenant && units.Contains(x.ChapterId)); }
    public async Task<IQueryable<Membership>> Directory(Guid tenant)
    {
        await access.Member(tenant); if (await access.Can(tenant, "members.read")) return db.Memberships.AsNoTracking().Where(m => m.TenantId == tenant); var now = DateTimeOffset.UtcNow; var mine = await (from m in db.Memberships join p in db.Persons on m.PersonId equals p.Id where m.TenantId == tenant && p.UserId == access.UserId && m.Status == "Active" && m.EffectiveFrom <= now && (m.EndsAt == null || m.EndsAt > now) select new { m.ChapterId }).ToListAsync(); var roots = new HashSet<Guid>();var exactChapters=new HashSet<Guid>(); bool society = false;
        foreach (var own in mine) { var policy = await Policy(tenant, own.ChapterId); if (policy.DirectoryScope is "society" or "international") society = true; else if (policy.DirectoryScope is "region" or "district") { Guid? parent = null; if (policy.DirectoryLevelId != null || policy.DirectoryScope == "region") { var level = policy.DirectoryLevelId; var ancestor = await db.Database.SqlQuery<Guid>($"""
WITH RECURSIVE ancestors AS (SELECT "Id","ParentId","LevelId",0 AS depth FROM "Units" WHERE "TenantId"={tenant} AND "Id"={own.ChapterId} UNION ALL SELECT p."Id",p."ParentId",p."LevelId",a.depth+1 FROM "Units" p JOIN ancestors a ON a."ParentId"=p."Id" WHERE p."TenantId"={tenant}) SELECT a."Id" AS "Value" FROM ancestors a JOIN "Levels" l ON l."Id"=a."LevelId" WHERE a.depth>0 AND (({level}::uuid IS NOT NULL AND l."Id"={level}) OR ({level}::uuid IS NULL AND l."Kind"='Region')) ORDER BY a.depth LIMIT 1
""").ToListAsync(); parent = ancestor.Count > 0 ? ancestor[0] : null; } parent ??= await db.Units.Where(x => x.TenantId == tenant && x.Id == own.ChapterId).Select(x => x.ParentId).SingleAsync(); if (parent != null) roots.Add(parent.Value); else exactChapters.Add(own.ChapterId); } else if (policy.DirectoryScope == "selected") { exactChapters.Add(own.ChapterId); foreach (var id in policy.SelectedChapters) exactChapters.Add(id); } else exactChapters.Add(own.ChapterId); }
        var rootIds=roots.ToArray();var exact=exactChapters.ToArray();var allowed=db.Database.SqlQuery<Guid>($"""
WITH RECURSIVE branch AS (SELECT "Id","ParentId" FROM "Units" WHERE "TenantId"={tenant} AND "Id"=ANY({rootIds}) UNION SELECT u."Id",u."ParentId" FROM "Units" u JOIN branch b ON u."ParentId"=b."Id" WHERE u."TenantId"={tenant}) SELECT "Id" AS "Value" FROM branch
""");
        var admin = Administrative(tenant).Select(x => x.Id); var billing = Administrative(tenant, "members.billing").Select(x => x.Id); var self = db.Persons.Where(x => x.UserId == access.UserId).Select(x => x.Id);
        return db.Memberships.FromSqlInterpolated($"SELECT * FROM \"Memberships\" WHERE \"TenantId\"={tenant}").AsNoTracking().Where(x => admin.Contains(x.Id) || billing.Contains(x.Id) || self.Contains(x.PersonId) || MembershipExperience.Owned(db, access.UserId).Select(m => m.Id).Contains(x.Id) || ((society || exact.Contains(x.ChapterId)||allowed.Contains(x.ChapterId)) && x.Status == "Active" && x.EffectiveFrom <= now && (x.EndsAt == null || x.EndsAt > now) && EF.Functions.JsonContains(x.Privacy, "{\"directory\":true}")));
    }
    public async Task<List<MemberCard>> Cards(Guid tenant, IQueryable<Membership> query)
    {
        var fullAdmin = await access.Can(tenant, "members.read"); var adminUnits = access.Visible(tenant, "members.read").Select(x => x.Id); var billingUnits = access.Visible(tenant, "members.billing").Select(x => x.Id); var now = DateTimeOffset.UtcNow;
        var rows = await (from m in query join p in db.Persons on m.PersonId equals p.Id join u in db.Units on m.ChapterId equals u.Id join c in db.MembershipCategories on m.CategoryId equals c.Id select new { m, p.FullName, u.Name, region = db.Units.Where(r => r.Id == u.ParentId).Select(r => r.Name).FirstOrDefault(), category = c.Name, admin = fullAdmin || adminUnits.Contains(m.ChapterId), billing = billingUnits.Contains(m.ChapterId), self = MembershipExperience.Owned(db, access.UserId, true).Select(owned => owned.Id).Contains(m.Id), designation = (from appointment in db.OfficerAppointments join position in db.OfficerPositions on appointment.PositionId equals position.Id where appointment.TenantId == tenant && appointment.MembershipId == m.Id && appointment.Status == "Approved" && appointment.StartsAt <= now && appointment.EndsAt > now select position.Name).FirstOrDefault() }).ToListAsync();
        var policies = await db.MembershipPolicies.Where(x => x.TenantId == tenant).AsNoTracking().ToListAsync(); return rows.Select(r => { var profile = Json(r.m.Profile); var privacy = Json(r.m.Privacy); bool Opt(string key) => privacy[key]?.GetValue<bool>() == true; var policy = policies.FirstOrDefault(x => x.ChapterId == r.m.ChapterId) ?? policies.FirstOrDefault(x => x.ChapterId == null); bool billingOnly = r.billing && !r.admin && !r.self; bool contact = r.admin || r.self || (!billingOnly && policy?.ContactsAllowed == true && Opt("contacts")); return new MemberCard(r.m.Id, r.admin || r.self ? r.m.PersonId : null, r.m.Number, r.FullName, r.m.ChapterId, r.Name, r.region ?? "", r.m.CategoryId, r.category, r.m.Status, r.m.JoinedAt, r.m.Revision, r.designation, Opt("photo") || r.admin || r.self ? profile["photoUrl"]?.GetValue<string>() : null, profile["city"]?.GetValue<string>(), !billingOnly && (Opt("professional") || r.admin || r.self) ? profile["professional"]?.DeepClone() : null, contact ? new { email = profile["email"]?.DeepClone(), phone = profile["phone"]?.DeepClone(), workEmail = profile["workEmail"]?.DeepClone() } : null, r.admin); }).ToList();
    }
    public async Task<Membership> Create(Guid tenant, Person person, Guid chapter, Guid category, string? number, string profile, Guid actor, string status = "Active", DateTimeOffset? joinedAt = null, DateTimeOffset? effectiveFrom = null, DateTimeOffset? endsAt = null)
    {
        await Chapter(tenant, chapter); await Category(tenant, category); if (person.UserId != null && await db.MembershipCategories.AnyAsync(c => c.TenantId == tenant && c.Id == category && c.Kind != "Individual")) throw new DomainException("Organization memberships require a separate organization holder and verified representative"); ValidateProfile(profile); var policy = await Policy(tenant, chapter); if (await db.Memberships.AnyAsync(x => x.TenantId == tenant && x.PersonId == person.Id && x.Status != "Closed" && x.Status != "Transferred" && (x.ChapterId == chapter || !policy.AllowMultipleChapters))) throw new DomainException("This person already holds a membership disallowed by chapter policy");
        number = string.IsNullOrWhiteSpace(number) ? "M-" + Guid.NewGuid().ToString("N")[..16].ToUpperInvariant() : number.Trim().ToUpperInvariant(); if (number.Length > 40 || !System.Text.RegularExpressions.Regex.IsMatch(number, "^[A-Z0-9_-]+$")) throw new DomainException("Invalid membership number"); var m = new Membership { TenantId = tenant, PersonId = person.Id, ChapterId = chapter, CategoryId = category, Number = number, Profile = profile, Status = status, JoinedAt = joinedAt?.ToUniversalTime() ?? DateTimeOffset.UtcNow, EffectiveFrom = effectiveFrom?.ToUniversalTime() ?? DateTimeOffset.UtcNow, EndsAt = endsAt?.ToUniversalTime() }; if (m.EndsAt <= m.EffectiveFrom) throw new DomainException("Membership end must follow its effective start"); await MembershipExperience.Prepare(db, m); db.Memberships.Add(m); await AddLinkAndDirectory(m, person); History(m, actor, "membership.created", new { chapter, category, status }); return m;
    }
    public Membership ImportRecord(Guid tenant,Guid chapter,Guid category,string fullName,string? number,string profile,Guid actor){ValidateProfile(profile);number=string.IsNullOrWhiteSpace(number)?"M-"+Guid.NewGuid().ToString("N")[..16].ToUpperInvariant():number.Trim().ToUpperInvariant();if(number.Length>40||!System.Text.RegularExpressions.Regex.IsMatch(number,"^[A-Z0-9_-]+$"))throw new DomainException("Invalid membership number");var person=new Person{FullName=fullName,SearchName=fullName.ToLowerInvariant()};db.Persons.Add(person);var member=new Membership{TenantId=tenant,PersonId=person.Id,ChapterId=chapter,CategoryId=category,Number=number,Profile=profile,Status="Inactive"};db.Memberships.Add(member);History(member,actor,"membership.imported",new{chapter,category});return member;}
    public async Task AddLinkAndDirectory(Membership m, Person person) { if (person.UserId == null) return; var user = person.UserId.Value; if (!await db.Links.AnyAsync(x => x.TenantId == m.TenantId && x.UserId == user) && !db.Links.Local.Any(x => x.TenantId == m.TenantId && x.UserId == user)) db.Links.Add(new Link { TenantId = m.TenantId, UserId = user }); var role = await db.GovernanceRoles.FirstOrDefaultAsync(x => x.TenantId == m.TenantId && x.Name == "Member Directory"); if (role == null) { role = new GovernanceRole { TenantId = m.TenantId, Name = "Member Directory", Permissions = ["units.read", "directory.chapter"] }; db.GovernanceRoles.Add(role); } if (!await db.Assignments.AnyAsync(x => x.TenantId == m.TenantId && x.MembershipId == m.Id && x.RoleId == role.Id)) db.Assignments.Add(new Assignment { TenantId = m.TenantId, UserId = user, RoleId = role.Id, UnitId = m.ChapterId, MembershipId = m.Id, StartsAt = m.EffectiveFrom, EndsAt = m.EndsAt }); }
    public async Task SyncDirectoryTerm(Membership member){var assignments=await (from assignment in db.Assignments join role in db.GovernanceRoles on assignment.RoleId equals role.Id where assignment.TenantId==member.TenantId&&assignment.MembershipId==member.Id&&role.Name=="Member Directory" select assignment).ToListAsync();foreach(var assignment in assignments){assignment.StartsAt=member.EffectiveFrom;assignment.EndsAt=member.EndsAt;}}
    public void History(Membership m, Guid actor, string action, object details) { db.MembershipHistories.Add(new MembershipHistory { TenantId = m.TenantId, MembershipId = m.Id, ActorId = actor, Action = action, Details = JsonSerializer.Serialize(details) }); db.Audits.Add(new Audit { TenantId = m.TenantId, ActorId = actor, Action = action, ResourceId = m.Id, Details = "{}" }); }
    public async Task RevokeOfficers(Membership m, Guid actor) { var now = DateTimeOffset.UtcNow; var appointments = await db.OfficerAppointments.Where(x => x.TenantId == m.TenantId && x.MembershipId == m.Id && x.Status == "Approved" && x.EndsAt > now).ToListAsync(); foreach (var appointment in appointments) { appointment.Status = "Revoked"; appointment.Revision++; if (appointment.AssignmentId is { } id) { var assignment = await db.Assignments.FindAsync(id); if (assignment != null) { assignment.RevokedAt = now; if (assignment.StartsAt >= now) assignment.EndsAt = assignment.StartsAt.AddTicks(10); else assignment.EndsAt = now; } } } History(m, actor, "leadership.access.revoked", new { count = appointments.Count }); }
}
